def format_duration(seconds: int) -> str:
    units = [
        (365 * 24 * 3600, "year"),
        (24 * 3600, "day"),
        (3600, "hour"),
        (60, "minute"),
        (1, "second"),
    ]
    parts = []
    for size, name in units:
        count, seconds = divmod(seconds, size)
        if count:
            parts.append(f"{count} {name if count == 1 else name + 's'}")
    if not parts:
        return "now"
    if len(parts) == 1:
        return parts[0]
    return ", ".join(parts[:-1]) + " and " + parts[-1]

def sort_versions(versions: list[str]) -> list[str]:
    def key(v):
        core, _, rest = v.partition('+')
        main, _, pre = core.partition('-')
        major, minor, patch = (int(x) for x in main.split('.'))
        if pre:
            ids = []
            for ident in pre.split('.'):
                if ident.isdigit():
                    ids.append((0, int(ident)))
                else:
                    ids.append((1, ident))
            pre_key = (0, ids)  # pre-release sorts before no pre-release
        else:
            pre_key = (1, ())
        return (major, minor, patch, pre_key)

    return sorted(versions, key=key)

def wrap_text(text: str, width: int) -> str:
    words = text.split()
    if not words:
        return ""

    lines = []
    cur = ""

    for w in words:
        if len(w) > width:
            if cur:
                lines.append(cur)
                cur = ""
            chunks = [w[i:i + width] for i in range(0, len(w), width)]
            for c in chunks[:-1]:
                lines.append(c)
            cur = chunks[-1]
        else:
            if not cur:
                cur = w
            elif len(cur) + 1 + len(w) <= width:
                cur += " " + w
            else:
                lines.append(cur)
                cur = w

    if cur:
        lines.append(cur)
    return "\n".join(lines)

def format_duration(seconds: int) -> str:
    if seconds == 0:
        return "now"

    units = [
        ("year", 365 * 24 * 3600),
        ("day", 24 * 3600),
        ("hour", 3600),
        ("minute", 60),
        ("second", 1),
    ]

    parts = []
    for name, size in units:
        count, seconds = divmod(seconds, size)
        if count:
            parts.append(f"{count} {name}" if count == 1 else f"{count} {name}s")

    if len(parts) == 1:
        return parts[0]
    if len(parts) == 2:
        return f"{parts[0]} and {parts[1]}"
    return ", ".join(parts[:-1]) + f" and {parts[-1]}"

import re


def _esc(c: str) -> str:
    if c in ("(", ")", "\\"):
        return "\\" + c
    return c


def rle_encode(s: str) -> str:
    out = []
    for length, ch in re.findall(r"(.)\1*", s):
        run = int(length)
        pieces = []
        while run > 0:
            n = min(run, 99)
            if n >= 3:
                pieces.append(f"({n}*{_esc(ch)})")
            else:
                pieces.append(_esc(ch) * n)
            run -= 99
        out.extend(pieces)
    return "".join(out)

