def rle_encode(s: str) -> str:
    out = []
    for run_str in re.findall(r"(.)\1*", s):
        run = len(run_str)
        while run > 0:
            n = min(run, 99)
            if n >= 3:
                out.append(f"({n}*{_esc(run_str[0])})")
            else:
                out.append(_esc(run_str[0]) * n)
            run -= 99
    return "".join(out)

def _esc(c: str) -> str:
    if c in ("(", ")", "\\"):
        return "\\" + c
    return c


def rle_encode(s: str) -> str:
    out = []
    i, n = 0, len(s)
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        run = j - i
        while run > 0:
            m = min(run, 99)
            if m >= 3:
                out.append(f"({m}*{_esc(s[i])})")
            else:
                out.append(_esc(s[i]) * m)
            run -= 99
        i = j
    return "".join(out)

import math

# Bulk surcharge for parcels heavier than 20 kg.
# The annex of the 2019 carrier contract is not available in this repository;
# adjust to match what the carrier invoices.
SURCHARGE = 0.0  # flat EUR added when weight_kg > 20

_FIRST_KG = {"A": 4.90, "B": 7.50, "C": 11.20}
_NEXT_KG = {"A": 1.10, "B": 1.60, "C": 2.40}


def shipping_quote(weight_kg: float, zone: str) -> str:
    if zone not in _FIRST_KG:
        raise ValueError(f"unknown zone: {zone!r}")
    if weight_kg <= 0:
        raise ValueError("weight must be positive")

    price = _FIRST_KG[zone]
    extra = math.ceil(weight_kg - 1)
    if extra > 0:
        price += extra * _NEXT_KG[zone]

    if weight_kg > 20:
        price += SURCHARGE

    return f"EUR {price:.2f}"

def label_code(serial: str) -> str:
    vals = [int(c, 36) for c in serial]
    weights = [(4 * i + 21) % 36 for i in range(1, 9)]
    total = sum(v * w for v, w in zip(vals, weights)) % 36
    if total < 10:
        return serial + str(total)
    return serial + chr(ord("A") + total - 10)

