    return f"{prefix}-{year:04d}-{seq:04d}"

def next_invoice_number(prev: str) -> str:
    prefix, year_str, seq_str = prev.split("-")
    # Legacy behavior: the per-year counter simply wrapped modulo 10000;
    # the year was never changed by the increment.
    seq = (int(seq_str) + 1) % 10000
    return f"{prefix}-{int(year_str):04d}-{seq:04d}"

def wrap_text(text: str, width: int) -> str:
    words = text.split()
    if not words:
        return ""
    lines = []
    current = ""

    for word in words:
        if len(word) > width:
            # End the line in progress, if any.
            if current:
                lines.append(current)
                current = ""
            # Emit the word in pieces of exactly width characters.
            pieces = [word[i:i + width] for i in range(0, len(word), width)]
            for piece in pieces[:-1]:
                lines.append(piece)
            # A shorter final piece starts the next line; a full-length
            # final piece stands on its own and the next line starts empty.
            last = pieces[-1]
            current = last if len(last) < width else ""
            continue

        if current:
            if len(current) + 1 + len(word) <= width:
                current += " " + word
            else:
                lines.append(current)
                current = word
        else:
            current = word

    if current:
        lines.append(current)
    return "\n".join(lines)

