def sort_versions(versions: list[str]) -> list[str]:
    def key(v):
        core, _, rest = v.partition("-")
        rest, _, _ = rest.partition("+")
        major, minor, patch = (int(p) for p in core.split("."))
        if rest:
            ids = []
            for ident in rest.split("."):
                if ident.isdigit():
                    ids.append((0, int(ident)))
                else:
                    ids.append((1, ident))
            pre = (0, ids)
        else:
            pre = (1, ())
        return (major, minor, patch, pre)

    return sorted(versions, key=key)

