def rle_encode(s: str) -> str:
    def esc(c: str) -> str:
        return "\\" + c if c in "()" or c == "\\" else c

    out = []
    n = len(s)
    i = 0
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        run = j - i
        c = esc(s[i])
        k = 0
        while k < run:
            take = min(99, run - k)
            if run - k == 99:
                # full piece of 99
                out.append("(99*%s)" % c)
            elif take >= 3:
                out.append("(%d*%s)" % (take, c))
            else:
                out.append(c * take)
            k += take
        i = j
    return "".join(out)

def format_duration(seconds: int) -> str:
    if seconds == 0:
        return "now"

    units = [
        (60 * 60 * 24 * 365, "year"),
        (60 * 60 * 24, "day"),
        (60 * 60, "hour"),
        (60, "minute"),
        (1, "second"),
    ]

    parts = []
    for value, name in units:
        count, seconds = divmod(seconds, value)
        if count:
            parts.append(f"{count} {name}" if count == 1 else f"{count} {name}s")

    if len(parts) == 1:
        return parts[0]
    return ", ".join(parts[:-2] + [parts[-2] + " and " + parts[-1]])

def wrap_text(text: str, width: int) -> str:
    words = text.split()
    lines = []
    current = ""
    for word in words:
        if len(word) > width:
            if current:
                lines.append(current)
                current = ""
            last = len(word) - (len(word) % width)
            for i in range(0, last, width):
                lines.append(word[i:i + width])
            if last < len(word):
                current = word[last:]
            # else: last piece is exactly `width` chars and has its own line
        elif not current:
            current = word
        else:
            if len(current) + 1 + len(word) <= width:
                current += " " + word
            else:
                lines.append(current)
                current = word
    if current:
        lines.append(current)
    return "\n".join(lines)

def sort_versions(versions: list[str]) -> list[str]:
    def key(v: str):
        # Strip build metadata (does not affect precedence)
        core = v.split("+", 1)[0]
        if "-" in core:
            base, pre = core.split("-", 1)
        else:
            base, pre = core, None
        major, minor, patch = (int(x) for x in base.split("."))

        if pre is None:
            # No pre-release: higher precedence than any pre-release of same version
            pre_key = (1,)
        else:
            parts = []
            for ident in pre.split("."):
                if ident.isdigit():
                    parts.append((0, int(ident), ""))
                else:
                    parts.append((1, 0, ident))
            pre_key = (0, parts)

        return (major, minor, patch, pre_key)

    return sorted(versions, key=key)

