import itertools
P = {"Highcliff": {"amber":43,"copper":47,"timber":51,"silk":24},
     "Thornwick": {"amber":36,"copper":42,"timber":47,"silk":43},
     "Stonebridge": {"amber":8,"copper":35,"timber":9,"silk":10}}
GOODS = list(P["Highcliff"].keys())
CAP, LAST = 30, 8
TOWNS = list(P.keys())
# state: (town, cargo_tuple) -> max gold
S = {("Highcliff", ()): 200}
best = 200
for day in range(1, LAST+1):
    NS = {}
    def add(town, cargot, gold):
        k = (town, cargot)
        if k not in NS or gold > NS[k]: NS[k] = gold
    for (town, cargot), gold in S.items():
        cargo = dict(cargot)
        opts = [range(0, cargo.get(g,0)+1) for g in GOODS]
        for qs in itertools.product(*opts):
            gld = gold; sold = 0
            cs = dict(cargo)
            for g,q in zip(GOODS,qs):
                if q: cs[g] -= q; gld += q*P[town][g]; sold += q
            cu = sum(cs.values())
            add(town, tuple(sorted((k,v) for k,v in cs.items() if v)), gld)
            # then buy (net effect: d_g >= -sold_g, total <= CAP, cost <= gld)
            # enumerate buys per good: 0..min(space, afford) but only extremes matter w/ single good; mixed buys:
            space = CAP - cu
            for g in GOODS:
                q = min(space, gld//P[town][g])
                cc = dict(cs); cc[g] = cc.get(g,0)+q
                add(town, tuple(sorted((k,v) for k,v in cc.items() if v)), gld - q*P[town][g])
        if day < LAST:
            for t in TOWNS:
                if t != town:
                    add(t, cargot, gold)
    S = NS
    best = max(best, max(S.values()))
    print("day", day, "states:", len(S), "max gold:", best)
print("MAX:", best)

