import math, time

def count_sq(n, s):
    counts = [0]*10
    for c in s:
        counts[ord(c)-48] += 1
    tsum = sum(counts)
    tsum_mod9 = tsum % 9
    tcounts = tuple(counts)
    max_k = math.isqrt(10**n - 1)
    cnt = 0
    for k in range(max_k + 1):
        sq = k*k
        if sq % 9 != tsum_mod9:
            continue
        d = sq % 10
        if counts[d] == 0:
            continue
        t = str(sq).zfill(n)
        cc = [0]*10
        for ch in t:
            cc[ord(ch)-48] += 1
        if tuple(cc) == tcounts:
            cnt += 1
    return cnt

