def format_duration(seconds: int) -> str:
    if seconds == 0:
        return "now"

    units = [
        (365 * 24 * 60 * 60, "year"),
        (24 * 60 * 60, "day"),
        (60 * 60, "hour"),
        (60, "minute"),
        (1, "second"),
    ]

    parts = []
    for value, name in units:
        count, seconds = divmod(seconds, value)
        if count:
            parts.append(f"{count} {name}" + ("" if count == 1 else "s"))

    if len(parts) == 1:
        return parts[0]
    return ", ".join(parts[:-2] + [parts[-2] + " and " + parts[-1]])

def wrap_text(text: str, width: int) -> str:
    words = text.split()
    if not words:
        return ""
    lines = []
    cur = ""
    for word in words:
        if len(word) > width:
            if cur:
                lines.append(cur)
                cur = ""
            chunks = [word[i:i + width] for i in range(0, len(word), width)]
            lines.extend(chunks[:-1])
            cur = chunks[-1]
        else:
            if cur == "":
                cur = word
            elif len(cur) + 1 + len(word) <= width:
                cur += " " + word
            else:
                lines.append(cur)
                cur = word
    if cur:
        lines.append(cur)
    return "\n".join(lines)

