def sort_versions(versions: list[str]) -> list[str]:
    def key(v: str):
        core, _, build = v.partition("+")
        if "-" in core:
            base, _, pre = core.partition("-")
        else:
            base, pre = core, None
        major, minor, patch = (int(x) for x in base.split("."))
        if pre is None:
            pre_key = (1,)  # no pre-release sorts above pre-releases
        else:
            ids = []
            for ident in pre.split("."):
                if ident.isdigit():
                    ids.append((0, int(ident), ""))
                else:
                    ids.append((1, 0, ident))
            pre_key = (0, ids)
        return (major, minor, patch, pre_key)

    return sorted(versions, key=key)

