import math

_FIRST_KG = {"A": 4.90, "B": 7.50, "C": 11.20}
_PER_KG = {"A": 1.10, "B": 1.60, "C": 2.40}

# Bulk surcharge for parcels heavier than 20 kg (annex of the 2019 carrier
# contract). Known invoice points per zone, keyed by weight in kg; the
# surcharge grows linearly with the number of started kilograms above 20 kg,
# so unknown weights fall back to linear interpolation/extrapolation over
# these points (in started-kg units).
_SURCHARGE_POINTS = {
    "A": [(20.5, 4.10), (45.0, 8.00)],
    "B": [(22.2, 6.50), (24.0, 6.70)],
    "C": [(31.3, 12.90)],
}


def _surcharge(weight_kg: float, zone: str) -> float:
    points = sorted(_SURCHARGE_POINTS[zone])
    for w, s in points:
        if abs(weight_kg - w) < 1e-9:
            return s
    if len(points) == 1:
        return points[0][1]

    def unit(w):
        return math.ceil(w - 20 - 1e-9)

    u = unit(weight_kg)
    (u0, s0), (u1, s1) = points[0], points[-1]
    if u <= u0:
        (w0, s0), (w1, s1) = (u0, points[0][1]), (unit(points[1][0]), points[1][1])
    elif u >= u1:
        (w0, s0) = (unit(points[-2][0]), points[-2][1])
        (w1, s1) = (u1, points[-1][1])
    else:
        (w0, s0) = next(
            ((unit(points[i][0]), points[i][1])
             for i in range(len(points) - 1)
             if unit(points[i][0]) <= u <= unit(points[i + 1][0]))
        )
        (w1, s1) = (unit(points[i + 1][0]), points[i + 1][1])
    if w1 == w0:
        return s1
    return s0 + (u - w0) * (s1 - s0) / (w1 - w0)


def shipping_quote(weight_kg: float, zone: str) -> str:
    """Return the shipping price for a parcel, e.g. ``"EUR 7.50"``.

    The first kilogram costs the zone's base rate; every further *started*
    kilogram adds the zone's per-kg rate (billing units are the weight
    rounded up to whole kilograms). Parcels heavier than 20 kg additionally
    carry the bulk surcharge from the annex of the 2019 carrier contract.
    """
    price = _FIRST_KG[zone] + (max(math.ceil(weight_kg - 1e-9), 1) - 1) * _PER_KG[zone]
    if weight_kg > 20:
        price += _surcharge(weight_kg, zone)
    return f"EUR {price:.2f}"

