            rest = rest[1:]
    elif digits.startswith('0'):
        rest = digits[1:]
    else:
        return 'INVALID'

    if not rest.isdigit() or len(rest) != 10 or rest[0] in '0456':
        return 'INVALID'

    d = rest
    if d[0] == '2':
        # Two-digit area codes (London 20, plus 23/24/28/29): 8 local
        # digits grouped 4/4, e.g. +44 20 7946 0958
        return f'+44 {d[:2]} {d[2:6]} {d[6:]}'
    if d[0] == '7':
        # Mobile: 4-digit opening, then the remaining 6 digits as one block
        return f'+44 {d[:4]} {d[4:]}'
    if d[0] == '1':
        # 3-digit area codes: 111, 113-117 (the 11x city codes) and
        # 121, 131, ..., 191 (ending in 1).  4-digit otherwise
        # (e.g. 1112, 1119, 1234, 1632).
        three = (d[1] == '1') != (d[2] == '1')
        if three:
            return f'+44 {d[:3]} {d[3:6]} {d[6:]}'
        return f'+44 {d[:4]} {d[4:7]} {d[7:]}'
    if d[0] in '38':
        # 0300/0333/0344/0370 and 0800/0845/0870/... : 3-digit area code,
        # 7 local digits grouped 3/4
        return f'+44 {d[:3]} {d[3:6]} {d[6:]}'
    # 09xx personal numbering and any other 4-digit area code: 3/3
    return f'+44 {d[:4]} {d[4:7]} {d[7:]}'

import re


def normalize_phone(raw: str) -> str:
    # Punctuation and spaces are ignored; '+' may appear at the start.
    if raw.startswith("+"):
        body = raw[1:]
        digits = re.sub(r"\D", "", body)
        if not digits.startswith("44"):
            return "INVALID"
        # Country code given: remainder may include a spurious (0).
        national = digits[2:]
    else:
        digits = re.sub(r"\D", "", raw)
        if digits.startswith("0044"):
            national = digits[4:]
        elif digits.startswith("0"):
            national = digits[1:]
        else:
            return "INVALID"

    # A (0) after the country code is dropped.
    if national.startswith("0") and len(national) == 11:
        national = national[1:]

    if len(national) != 10:
        return "INVALID"

    if national.startswith("20"):
        return "+44 20 {} {}".format(national[2:6], national[6:])
    if national.startswith("7"):
        return "+44 {} {}".format(national[:4], national[4:])
    return "+44 {} {} {}".format(national[:3], national[3:6], national[6:])

